window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-978175f67010d0a2"]={"versions": [{"id": "FIG-978175f67010d0a2", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Speicherlayout- und Datenflussdiagramm (Buffer Layout / Transformation Process) zur Pufferverwaltung des E2E-Transformers (<code>E2EXf_&lt;transformerId&gt;</code>) innerhalb der AUTOSAR-Basissoftware (Transformer-Kette im RTE-/Kommunikationsstack).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Pufferkomponenten:</li>\n<li><code>Header</code>: Protokoll-/Transformationsheader vorgelagerter Transformer (z. B. SOME/IP-Header).</li>\n<li><code>Payload</code>: Nutzdatenbereich der serialisierten Nachricht.</li>\n<li><code>unused</code>: Reservierter, führender Freibereich im Puffer.</li>\n<li><code>E2E Header</code>: Vom E2E-Transformer eingefügter E2E-spezifischer Schutzheader (z. B. Counter, CRC).</li>\n<li>Konfigurationsparameter & Metriken:</li>\n<li><code>inputBufferLength</code>: Gesamtlänge des Eingabepuffers des vorherigen Transformers in Bytes.</li>\n<li><code>&lt;BufferProperties.headerLength&gt;</code>: Länge des reservierten Pufferkopfbereichs in Bits.</li>\n<li><code>&lt;EndToEndTransformationDescription.upperHeaderBitsToShift&gt;</code>: Länge des vorgelagerten Headers in Bits, der nach vorne verschoben wird.</li>\n<li><code>BufferLength</code>: Resultierende Gesamtlänge des Puffers nach Durchführung der Verschiebung und E2E-Header-Einfügung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Puffers vom vorherigen Transformer mit <code>Header</code> und <code>Payload</code> über die Länge <code>inputBufferLength</code>.</li>\n<li>Bereitstellung eines Speicherbereichs mit <code>&lt;BufferProperties.headerLength&gt;</code> führenden, ungenutzten Bits vor dem ursprünglichen Pufferinhalt.</li>\n<li>Verschieben des bestehenden Headers (<code>&lt;EndToEndTransformationDescription.upperHeaderBitsToShift&gt;</code> Bits) an den Pufferanfang ([SWS_E2EXf_00108]).</li>\n<li>Einfügen des <code>E2E Header</code> in die entstandene Lücke zwischen dem verschobenen <code>Header</code> und der <code>Payload</code>.</li>\n<li>Aktualisierung der Pufferlänge auf <code>BufferLength = inputBufferLength + &lt;BufferProperties.headerLength&gt;/8</code> ([SWS_E2EXf_00111]).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>[SWS_E2EXf_00108]: Verpflichtende Verschiebung der oberen Header-Bits (<code>upperHeaderBitsToShift</code>) an die Anfangsadresse des Gesamtpuffers.</li>\n<li>[SWS_E2EXf_00111]: Vorgeschriebene Berechnung der Ausgabepufferlänge durch Addition der Header-Länge in Bytes (<code>&lt;BufferProperties.headerLength&gt;/8</code>) zur ursprünglichen <code>inputBufferLength</code>.</li>\n<li>Implementierungshinweis: Voraussetzung ist eine In-Place-Pufferallokation mit ausreichendem Headroom (<code>headerLength</code>), um zusätzliche Puffer-Reallokationen innerhalb der Transformer-Kette zu vermeiden. Bit- und Bytegrenzen müssen gemäß Konfiguration exakt berücksichtigt werden.</li>\n</ul>"}, {"id": "FIG-a430b9ec35504505", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Speicherlayout- und Datenflussdiagramm (Buffer Layout / Transformation Process) zur Pufferverwaltung des E2E-Transformers (<code>E2EXf_&lt;transformerId&gt;</code>) innerhalb der AUTOSAR-Basissoftware (Transformer-Kette im RTE-/Kommunikationsstack).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Pufferkomponenten:</li>\n<li><code>Header</code>: Protokoll-/Transformationsheader vorgelagerter Transformer (z. B. SOME/IP-Header).</li>\n<li><code>Payload</code>: Nutzdatenbereich der serialisierten Nachricht.</li>\n<li><code>unused</code>: Reservierter, führender Freibereich im Puffer.</li>\n<li><code>E2E Header</code>: Vom E2E-Transformer eingefügter E2E-spezifischer Schutzheader (z. B. Counter, CRC).</li>\n<li>Konfigurationsparameter & Metriken:</li>\n<li><code>inputBufferLength</code>: Gesamtlänge des Eingabepuffers des vorherigen Transformers in Bytes.</li>\n<li><code>&lt;BufferProperties.headerLength&gt;</code>: Länge des reservierten Pufferkopfbereichs in Bits.</li>\n<li><code>&lt;EndToEndTransformationDescription.upperHeaderBitsToShift&gt;</code>: Länge des vorgelagerten Headers in Bits, der nach vorne verschoben wird.</li>\n<li><code>BufferLength</code>: Resultierende Gesamtlänge des Puffers nach Durchführung der Verschiebung und E2E-Header-Einfügung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Puffers vom vorherigen Transformer mit <code>Header</code> und <code>Payload</code> über die Länge <code>inputBufferLength</code>.</li>\n<li>Bereitstellung eines Speicherbereichs mit <code>&lt;BufferProperties.headerLength&gt;</code> führenden, ungenutzten Bits vor dem ursprünglichen Pufferinhalt.</li>\n<li>Verschieben des bestehenden Headers (<code>&lt;EndToEndTransformationDescription.upperHeaderBitsToShift&gt;</code> Bits) an den Pufferanfang ([SWS_E2EXf_00108]).</li>\n<li>Einfügen des <code>E2E Header</code> in die entstandene Lücke zwischen dem verschobenen <code>Header</code> und der <code>Payload</code>.</li>\n<li>Aktualisierung der Pufferlänge auf <code>BufferLength = inputBufferLength + &lt;BufferProperties.headerLength&gt;/8</code> ([SWS_E2EXf_00111]).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>[SWS_E2EXf_00108]: Verpflichtende Verschiebung der oberen Header-Bits (<code>upperHeaderBitsToShift</code>) an die Anfangsadresse des Gesamtpuffers.</li>\n<li>[SWS_E2EXf_00111]: Vorgeschriebene Berechnung der Ausgabepufferlänge durch Addition der Header-Länge in Bytes (<code>&lt;BufferProperties.headerLength&gt;/8</code>) zur ursprünglichen <code>inputBufferLength</code>.</li>\n<li>Implementierungshinweis: Voraussetzung ist eine In-Place-Pufferallokation mit ausreichendem Headroom (<code>headerLength</code>), um zusätzliche Puffer-Reallokationen innerhalb der Transformer-Kette zu vermeiden. Bit- und Bytegrenzen müssen gemäß Konfiguration exakt berücksichtigt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-978175f67010d0a2", "to": "FIG-a430b9ec35504505", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Oberer Rand / Beschnitt: Am oberen Bildrand ist eine abgeschnittene Textzeile („left by 'distance' of BufferProperties.headerLength.] (SRS_E2E_08538)“) aus dem umgebenden Fließtext sichtbar.</li>\n</ul>"}, {"from": "FIG-a430b9ec35504505", "to": "FIG-978175f67010d0a2", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Oberer Rand / Beschnitt: Die am oberen Bildrand unbeabsichtigt sichtbare abgeschnittene Fließtextzeile („left by 'distance' of BufferProperties.headerLength.] (SRS_E2E_08538)“) wurde entfernt.</li>\n</ul>"}]};
